"""Add bounded diagnostics to generated JFG RSP code; rerun after RSPRecomp."""
from pathlib import Path
import re

target = Path(__file__).resolve().parents[1] / "rsp/n_aspMain.cpp"
source = target.read_text()
if "jfg_rsp_task_id" in source:
    raise SystemExit("Audio RSP diagnostics already present; regenerate first")
helpers = r'''
// Generated by tools/instrument_audio_rsp.py, preserved by regeneration script.
#include <cstdlib>
static const bool jfg_rsp_trace_enabled = [] {
    const char* value = std::getenv("JFG_TRACE_AUDIO");
    return value != nullptr && value[0] != '\0' && value[0] != '0';
}();
static thread_local unsigned long long jfg_rsp_task_id = 0;
static thread_local unsigned long long jfg_rsp_label_count = 0;
static thread_local unsigned jfg_rsp_dma_count = 0;
static bool jfg_rsp_visit(unsigned pc, unsigned r26, unsigned r25, unsigned r27, unsigned r30) {
    if (!jfg_rsp_trace_enabled) return true;
    if (++jfg_rsp_label_count <= 5000000) return true;
    fprintf(stderr, "[JFG RSP] LOOP BUDGET task=%llu pc=%04X cmd=%08X/%08X remaining=%08X chunk=%08X\n",
        jfg_rsp_task_id, pc, r26, r25, r27, r30);
    fflush(stderr);
    return false;
}
static void jfg_rsp_dma(const char* direction, unsigned mem, unsigned dram, unsigned length) {
    if (!jfg_rsp_trace_enabled) return;
    if (jfg_rsp_task_id <= 8 && jfg_rsp_dma_count++ < 32) {
        fprintf(stderr, "[JFG RSP] DMA task=%llu %s mem=%04X dram=%08X len=%08X\n",
            jfg_rsp_task_id, direction, mem, dram, length);
        fflush(stderr);
    }
}
'''
source = source.replace('using RspUcodePermutationFunc', helpers + '\nusing RspUcodePermutationFunc', 1)
source = source.replace('    RspContext ctx{};', '''    if (jfg_rsp_trace_enabled) {
        ++jfg_rsp_task_id;
        jfg_rsp_label_count = 0;
        jfg_rsp_dma_count = 0;
    }
    const bool trace = jfg_rsp_trace_enabled && jfg_rsp_task_id <= 8;
    if (trace) {
        fprintf(stderr, "[JFG RSP] ENTER task=%llu ucode=%08X dmem_ucode=%08X ucode_data=%08X data=%08X size=%08X headers=%08X/%08X\\n",
            jfg_rsp_task_id, ucode_addr, RSP_MEM_W_LOAD(0xFD0, 0),
            RSP_MEM_W_LOAD(0xFD8, 0),
            RSP_MEM_W_LOAD(0xFF0, 0), RSP_MEM_W_LOAD(0xFF4, 0),
            RSP_MEM_W_LOAD(0, 0), RSP_MEM_W_LOAD(8, 0));
        const unsigned data = RSP_MEM_W_LOAD(0xFF0, 0);
        const unsigned size = RSP_MEM_W_LOAD(0xFF4, 0);
        for (unsigned i = 0; i < 4 && i * 8 + 8 <= size; ++i) {
            const int64_t addr = static_cast<int32_t>((data & 0xFFFFFF) | 0x80000000U);
            fprintf(stderr, "[JFG RSP] COMMAND task=%llu index=%u words=%08X/%08X\\n",
                jfg_rsp_task_id, i, static_cast<unsigned>(MEM_W(i * 8, addr)),
                static_cast<unsigned>(MEM_W(i * 8 + 4, addr)));
        }
        fflush(stderr);
    }
    RspContext ctx{};''', 1)
source = source.replace('    while (exitReason == RspExitReason::SwapOverlay) {', '''    unsigned swap_count = 0;
    if (trace) { fprintf(stderr, "[JFG RSP] INITIAL RETURN task=%llu reason=%d\\n", jfg_rsp_task_id, static_cast<int>(exitReason)); fflush(stderr); }
    while (exitReason == RspExitReason::SwapOverlay) {
        if (trace && swap_count++ < 32) {
            fprintf(stderr, "[JFG RSP] SWAP task=%llu mem=%04X dram=%08X offset=%08X resume=%04X delay=%d jump=%04X\\n",
                jfg_rsp_task_id, ctx.dma_mem_address, ctx.dma_dram_address,
                ctx.dma_dram_address - ucode_addr, ctx.resume_address, ctx.resume_delay, ctx.jump_target);
            fflush(stderr);
        }''', 1)
source = source.replace('    return exitReason;', '''    if (trace) { fprintf(stderr, "[JFG RSP] EXIT task=%llu reason=%d labels=%llu\\n", jfg_rsp_task_id, static_cast<int>(exitReason), jfg_rsp_label_count); fflush(stderr); }
    return exitReason;''', 1)
source = re.sub(r'^(L_([0-9A-Fa-f]+):)$', lambda m: m[1] + '\n    if (!jfg_rsp_visit(0x' + m[2] + ', r26, r25, r27, r30)) return RspExitReason::Unsupported;', source, flags=re.M)
source = re.sub(r'^(\s*)DO_DMA_(READ|WRITE)\(([^)]+)\);', lambda m: m[1] + f'jfg_rsp_dma("{m[2]}", dma_mem_address, dma_dram_address, {m[3]});\n' + m[0], source, flags=re.M)
target.write_text(source)
